parameters.jsCode:
// Resuelve la herramienta que pidió el agente (entrega final: planilla única, búsqueda por comprobante o por remito/CTG).
// Toda la lógica de negocio está acá, no en la IA:
// quién es el transportista, si la factura es suya, si está a término y si corresponde un reclamo.
const p = $('Recibir pedido del agente').first().json;
const claveHash = $('Hashear clave').first().json.clave_hash;
// Cada hoja la lee un nodo de Google Sheets; acá se pasan todos los valores a texto para comparar sin sorpresas
const leer = n => $(n).all().map(i => i.json).filter(o => Object.keys(o).length)
  .map(o => Object.fromEntries(Object.entries(o).map(([k, v]) => [k, v == null ? '' : String(v)])));
const hojas = { Transportistas: leer('Leer transportistas'), Facturas: leer('Leer facturas'), Viajes: leer('Leer viajes'),
                Libro: leer('Leer libro'), Sesiones: leer('Leer sesiones'), Reclamos: leer('Leer reclamos'), Feriados: leer('Leer feriados') };
const P = Object.fromEntries(leer('Leer parámetros').map(p => [p.parametro, p.valor]));
const digitos = s => String(s ?? '').replace(/\D/g, '');
const norm = s => digitos(s).replace(/^0+/, '');
const ahora = new Date();
// fecha de Argentina (UTC-3), o la de prueba si Parametros tiene fecha_ejecucion
const hoy = P.fecha_ejecucion ? String(P.fecha_ejecucion).slice(0, 10) : new Date(ahora.getTime() - 3 * 3600000).toISOString().slice(0, 10);

// Días hábiles: sin sábados, domingos ni feriados de la hoja Feriados
const feriados = new Set(hojas.Feriados.map(f => f.fecha));
const habil = d => ![0, 6].includes(d.getUTCDay()) && !feriados.has(d.toISOString().slice(0, 10));
const mover = (iso, n) => { const d = new Date(iso + 'T00:00:00Z'); const paso = n > 0 ? 1 : -1;
  while (n) { d.setUTCDate(d.getUTCDate() + paso); if (habil(d)) n -= paso; } return d.toISOString().slice(0, 10); };
const fmt = iso => iso ? iso.split('-').reverse().join('/') : '';

// El transportista puede escribir el comprobante completo (0003-00011036), solo el número (11036)
// o el remito/CTG del viaje: en ese caso se busca en Viajes la factura que lo incluye
const buscarFactura = (idT, texto) => {
  const nro = norm(texto);
  if (!nro) return { f: null, cant: 0, por: '' };
  const propias = hojas.Facturas.filter(x => x.id_transportista === idT);
  let fs = propias.filter(x => norm(x.nro_comprobante) === nro || norm(String(x.nro_comprobante).split('-').pop()) === nro);
  let por = 'comprobante', remito = '';
  if (fs.length === 0) {
    const vs = hojas.Viajes.filter(v => norm(v.remito_ctg) === nro && propias.some(f => f.id_factura === v.id_factura));
    fs = [...new Set(vs.map(v => v.id_factura))].map(id => propias.find(f => f.id_factura === id));
    if (vs.length) { por = 'remito'; remito = vs[0].remito_ctg; }
  }
  return { f: fs.length === 1 ? fs[0] : null, cant: fs.length, por, remito };
};
const textoCaso = { 'Carga no cargada en TMS': 'el viaje todavía no figura en el sistema de cargas y lo estamos gestionando',
  'Consulta G4': 'la carga del viaje figura asociada a otra factura y la estamos revisando',
  'Posible remito mal cargado': 'el remito del viaje figura cargado con una diferencia y lo estamos corrigiendo',
  'Revisión manual': 'un analista está revisando el viaje' };

// Sesión: el transportista sale de la hoja Sesiones por el teléfono del mensaje, nunca de lo que diga la IA
const ses = hojas.Sesiones.find(s => s.telefono === p.telefono && s.valida_hasta > ahora.toISOString());
const trans = ses ? hojas.Transportistas.find(t => t.id_transportista === ses.id_transportista) : null;

let resultado = {}, escritura = 'ninguna', datos = {};

function situacion(f) {
  const desde = mover(f.fecha_vencimiento, -1), hasta = mover(f.fecha_vencimiento, 3);
  const base = { comprobante: f.nro_comprobante, importe: Number(f.importe), vencimiento: fmt(f.fecha_vencimiento),
                 ventana_de_pago: `${fmt(desde)} al ${fmt(hasta)}` };
  if (f.estado_pago === 'Pagada') return { ...base, estado: 'pagada', fecha_pago: fmt(f.fecha_pago), a_termino: f.fecha_pago <= hasta };
  if (f.estado_pago === 'Rechazada') return { ...base, estado: 'rechazada', motivo_rechazo: f.motivo_rechazo };
  const aTermino = hoy <= hasta;
  const caso = hojas.Libro.find(c => c.id_factura === f.id_factura && c.estado !== 'Resuelto');
  if (caso) base.situacion = textoCaso[caso.categoria] ?? textoCaso['Revisión manual'];
  return { ...base, estado: 'recibida_en_proceso', a_termino: aTermino,
           fecha_estimada_pago: aTermino ? `entre el ${fmt(hoy > desde ? hoy : desde)} y el ${fmt(hasta)}` : '',
           puede_reclamar: !aTermino };
}

if (p.accion === 'validar_identidad') {
  const t = hojas.Transportistas.find(t => digitos(t.cuit) === digitos(p.cuit));
  if (!t) resultado = { ok: false, motivo: 'cuit_no_registrado' };
  else if (t.estado_clave === 'Bloqueada') resultado = { ok: false, motivo: 'clave_bloqueada', puede_pedir_clave: true };
  else if (t.estado_clave !== 'Activa') resultado = { ok: false, motivo: 'sin_clave_generada', puede_pedir_clave: true };
  else if (!p.clave) resultado = { ok: false, motivo: 'falta_clave' };
  else if (claveHash !== t.clave_hash) {
    const intentos = Number(t.intentos_fallidos || 0) + 1;
    const bloquea = intentos >= 3;
    resultado = { ok: false, motivo: bloquea ? 'clave_bloqueada' : 'clave_incorrecta', intentos_restantes: Math.max(0, 3 - intentos), puede_pedir_clave: bloquea };
    escritura = 'intento_fallido';
    datos = { id_transportista: t.id_transportista, intentos_fallidos: intentos, estado_clave: bloquea ? 'Bloqueada' : 'Activa' };
  } else {
    resultado = { ok: true, razon_social: t.razon_social, sesion_valida_minutos: 30 };
    escritura = 'sesion';
    datos = { telefono: p.telefono, id_transportista: t.id_transportista, razon_social: t.razon_social,
              valida_hasta: new Date(ahora.getTime() + 30 * 60000).toISOString(), estado: 'Activa' };
  }
} else if (p.accion === 'consultar_factura') {
  if (!trans) resultado = { ok: false, motivo: 'sin_sesion' };
  else {
    // Solo facturas de este transportista: la de otro da "no recibida", igual que una que no existe
    const { f, cant, por } = buscarFactura(trans.id_transportista, p.nro_comprobante);
    if (!norm(p.nro_comprobante)) resultado = { ok: false, motivo: 'falta_comprobante' };
    else if (cant > 1) resultado = { ok: false, motivo: 'numero_ambiguo_pedir_punto_de_venta' };
    else resultado = f ? { ok: true, encontrada_por: por, ...situacion(f) } : { ok: true, estado: 'no_recibida', comprobante: p.nro_comprobante, puede_reclamar: true };
  }
} else if (p.accion === 'listar_pendientes') {
  if (!trans) resultado = { ok: false, motivo: 'sin_sesion' };
  else {
    const fs = hojas.Facturas.filter(x => x.id_transportista === trans.id_transportista && x.estado_pago === 'En proceso')
      .sort((a, b) => a.fecha_vencimiento.localeCompare(b.fecha_vencimiento)).map(situacion);
    resultado = { ok: true, cantidad: fs.length, facturas: fs.slice(0, 8), aclaracion: fs.length > 8 ? 'Se muestran las 8 más próximas a vencer' : '' };
  }
} else if (p.accion === 'abrir_reclamo') {
  const tipos = ['generacion_clave', 'factura_no_recibida', 'fuera_de_termino', 'disconformidad', 'derivar_a_persona'];
  const tipo = String(p.tipo_reclamo || '').trim();
  let t = trans, f = null, error = '', hallazgo = {};
  if (!tipos.includes(tipo)) error = 'tipo_invalido';
  else if (tipo === 'generacion_clave') {
    t = hojas.Transportistas.find(x => digitos(x.cuit) === digitos(p.cuit));
    if (!t) error = 'cuit_no_registrado';
  } else if (!t) error = 'sin_sesion';
  else if (tipo !== 'derivar_a_persona') {
    const nro = norm(p.nro_comprobante);
    hallazgo = buscarFactura(t.id_transportista, p.nro_comprobante); f = hallazgo.f;
    if (!nro) error = 'falta_comprobante';
    else if (tipo === 'factura_no_recibida' && f) error = 'la_factura_si_fue_recibida';
    else if (tipo === 'fuera_de_termino' && (!f || situacion(f).estado !== 'recibida_en_proceso' || situacion(f).a_termino)) error = 'la_factura_no_esta_fuera_de_termino';
    else if (tipo === 'disconformidad' && !f) error = 'factura_no_encontrada';
  }
  // Un solo reclamo abierto por tipo y comprobante (o por CUIT si es de clave): si ya existe, se informa el mismo
  const clave = tipo === 'generacion_clave' ? digitos(p.cuit) : norm(p.nro_comprobante);
  const previo = !error && hojas.Reclamos.find(r => r.tipo === tipo && r.estado === 'Abierto' &&
    (tipo === 'generacion_clave' ? digitos(r.cuit) === clave : (r.id_transportista === t.id_transportista && norm(r.nro_comprobante) === norm(f ? f.nro_comprobante : p.nro_comprobante))));
  if (error) resultado = { ok: false, motivo: error };
  else if (previo) resultado = { ok: true, id_reclamo: previo.id_reclamo, ya_existia: true, respuesta_por: 'mail registrado' };
  else {
    const id = 'R-' + hoy.slice(2).replace(/-/g, '') + '-W' + String(hojas.Reclamos.length + 1).padStart(3, '0');
    resultado = { ok: true, id_reclamo: id, ya_existia: false, respuesta_por: 'mail registrado', plazo: '48 horas hábiles' };
    escritura = 'reclamo';
    datos = { id_reclamo: id, fecha_alta: hoy, canal: 'WhatsApp', tipo, telefono: p.telefono, id_transportista: t.id_transportista,
              cuit: t.cuit, nro_comprobante: f ? f.nro_comprobante : (p.nro_comprobante || ''), remito_ctg: hallazgo.remito || '',
              id_factura: f ? f.id_factura : '', detalle: String(p.detalle || '').slice(0, 300),
              estado: 'Abierto', razon_social: t.razon_social, email_contacto: t.email_contacto };
  }
} else {
  resultado = { ok: false, motivo: 'accion_desconocida' };
}

return [{ json: { resultado, escritura, datos } }];

